import httpx

url_base = "http://harness:5000"

async def run_query(task_id):
    async with httpx.AsyncClient() as client:
        response = await client.get(f"{url_base}/query", params={
            "task_id": task_id,
            "radius": 2
        })
        return response.json()

result = await run_query("task-4718c1f8")
for i, data in enumerate(result):
    print(f"Demo {i}:")
    print("Input:")
    for row in data['input_rows']:
        print("  ", " ".join(str(c) for c in row))
    print("Output:")
    for row in data['output_rows']:
        print("  ", " ".join(str(c) for c in row))
    print()

